def _upload(self, composer, payload, artifacts):
        if not artifacts:
            return []
        container = composer.locator(self._dom_contract.area)
        scope = container.locator('xpath=..') if self._dom_contract == RAIL_INPUT_GROUP else container
        if self._dom_contract == RAIL_INPUT_GROUP and scope.get_attribute('role') != 'presentation':
            raise NotSubmitted('UNAVAILABLE')
        picker = scope.locator(self._dom_contract.picker)
        if picker.count() != 1:
            raise NotSubmitted('UNAVAILABLE')
        files, names = [], []
        for target, raw, witness in artifacts:
            name = payload['marker'] + '-' + witness['timeframe'] + '-' + witness['sha256'][:12] + '.png'
            names.append(name)
            files.append(dict(name=name, mimeType='image/png', buffer=raw))
        picker.set_input_files(files, timeout=self._timeout(10000))
        # The FileReader preview contains the exact original PNG as a data URL
        # and its filename, in a sibling preceding the active composer.
        deadline = self._until(30)
        while self.clock() < deadline:
            if self.status() != 'CONNECTED':
                raise NotSubmitted('UNAVAILABLE')
            if self._attachments_ready(container, names, artifacts):
                self.uploaded_names = list(names)
                return [{**witness, 'attachment_id': 'dom-' + hashlib.sha256(
                    (payload['marker'] + ':' + name + ':' + witness['sha256']).encode()).hexdigest()}
                    for name, (_, _, witness) in zip(names, artifacts)]
            self.page.wait_for_timeout(250)
        raise NotSubmitted('UNAVAILABLE')

