def image_artifacts(paths, evidence, *, max_age=None):
    """Validate local PNGs and their private archive witnesses before uploading."""
    if len(paths) != len(evidence) or len(paths) not in (0, 2):
        raise NotSubmitted('UNAVAILABLE')
    try:
        max_age = int(os.getenv('OFFICE_MARKET_MAX_AGE', '180')) if max_age is None else max_age
        if type(max_age) is not int or not 30 <= max_age <= 300:
            raise ValueError()
    except (TypeError, ValueError):
        raise NotSubmitted('UNAVAILABLE') from None
    result = []
    for path, witness in zip(paths, evidence):
        target = Path(path)
        if target.is_symlink() or not target.is_file():
            raise NotSubmitted('UNAVAILABLE')
        raw = target.read_bytes()
        if not 1024 <= len(raw) <= 8000000 or not png_valid(raw):
            raise NotSubmitted('UNAVAILABLE')
        if (witness.get('source') != 'BINANCE_USDM_FUTURES_WEBSITE_SCREENSHOT'
                or witness.get('sha256') != hashlib.sha256(raw).hexdigest()
                or witness.get('bytes') != len(raw)
                or witness.get('timeframe') not in ('15m', '1h')
                or not re.fullmatch(r'[A-Z0-9]{2,24}USDT', witness.get('symbol', ''))):
            raise NotSubmitted('UNAVAILABLE')
        try:
            captured = datetime.fromisoformat(witness['captured_at'].replace('Z', '+00:00'))
            age = (datetime.now(timezone.utc) - captured).total_seconds()
            if captured.utcoffset().total_seconds() != 0 or not 0 <= age <= max_age:
                raise ValueError()
        except (KeyError, ValueError, AttributeError, TypeError):
            raise NotSubmitted('UNAVAILABLE') from None
        item = dict(witness)
        item.pop('attachment_id', None)
        result.append((target, raw, item))
    if result and (set(item[2]['timeframe'] for item in result) != {'15m', '1h'}
            or len(set(item[2]['symbol'] for item in result)) != 1
            or len(set(item[2]['sha256'] for item in result)) != 2):
        raise NotSubmitted('UNAVAILABLE')
    return result

