def request_kind(payload, artifacts):
    schema = payload.get('output_schema')
    required = schema.get('required') if isinstance(schema, dict) else None
    if not isinstance(required, list) or any(not isinstance(key, str) for key in required):
        raise NotSubmitted('UNAVAILABLE')
    if set(required) == {'symbols'} and not artifacts:
        return 'screening'
    if set(required) != {'symbol', 'side', 'limit_entry', 'take_profit', 'stop_loss', 'risk_reward'}:
        raise NotSubmitted('UNAVAILABLE')
    context = payload.get('context')
    if (len(artifacts) != 2 or not isinstance(context, dict) or context.get('source') != 'Binance Futures'
            or not isinstance(context.get('timeframes'), dict)
            or set(context['timeframes']) != {'15m', '1h'}
            or any(item[2]['symbol'] != context.get('symbol') for item in artifacts)):
        raise NotSubmitted('UNAVAILABLE')
    for timeframe in ('15m', '1h'):
        chart = context['timeframes'][timeframe]
        if not isinstance(chart, dict) or chart.get('symbol') != context['symbol'] or chart.get('timeframe') != timeframe:
            raise NotSubmitted('UNAVAILABLE')
    return 'analysis'
